package org.simpleweather.qa;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import java.io.*;
import java.lang.reflect.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import java.util.concurrent.atomic.AtomicReference;
import org.json.*;

/** Verifies archive isolation and storage ownership against the production implementation. */
public final class AppDataManagerUiTests extends Instrumentation {
    private Context context;private ClassLoader loader;private int checks;private Activity activity;private Object apps;
    private final Map<String,Boolean> installedBefore=new LinkedHashMap<>();
    private final Map<String,Map<String,?>> preferences=new LinkedHashMap<>();
    private final Map<File,File> directories=new LinkedHashMap<>();
    private final List<File> outputs=new ArrayList<>();
    public void onCreate(Bundle args){super.onCreate(args);start();}
    private Class<?> type(String name)throws Exception{return Class.forName("org.daidai.toolbox."+name,true,loader);}
    private Object call(Object owner,String name,Class<?>[] args,Object...values)throws Exception{Class<?> c=owner instanceof Class?(Class<?>)owner:owner.getClass();Method m=c.getDeclaredMethod(name,args);m.setAccessible(true);return m.invoke(owner instanceof Class?null:owner,values);}
    private void check(boolean condition,String description){if(!condition)throw new AssertionError(description);checks++;}
    private void ui(Runnable task){AtomicReference<Throwable> failure=new AtomicReference<>();runOnMainSync(()->{try{task.run();}catch(Throwable e){failure.set(e);}});if(failure.get()!=null)throw new RuntimeException(failure.get());waitForIdleSync();}
    private void await(java.util.function.BooleanSupplier condition,String description)throws Exception{long deadline=SystemClock.elapsedRealtime()+10000;while(!condition.getAsBoolean()&&SystemClock.elapsedRealtime()<deadline)Thread.sleep(25);check(condition.getAsBoolean(),description);}
    private SharedPreferences prefs(String group){return context.getSharedPreferences(group,0);}
    private void remember(String group){if(!preferences.containsKey(group))preferences.put(group,new HashMap<>(prefs(group).getAll()));}
    private File data(String id){return new File(context.getFilesDir(),"internal-app-data/"+id);}
    private File cache(String id){return new File(context.getCacheDir(),"internal-"+id);}
    private void isolate(File file)throws Exception{if(directories.containsKey(file))return;File backup=new File(file.getParentFile(),"qa-previous-"+UUID.randomUUID());if(file.exists())Files.move(file.toPath(),backup.toPath());directories.put(file,backup);file.mkdirs();}
    private File write(File root,String name,String text)throws Exception{root.mkdirs();File f=new File(root,name);f.getParentFile().mkdirs();Files.write(f.toPath(),text.getBytes(StandardCharsets.UTF_8));return f;}
    private String read(File file)throws Exception{return new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);}
    private File exportApp(String id)throws Exception{File f=(File)call(type("InternalDataBackup"),"exportApp",new Class[]{Context.class,String.class},context,id);outputs.add(f);return f;}
    private Object prepare(File f,String id)throws Exception{return call(type("InternalDataBackup"),"readApp",new Class[]{Context.class,Uri.class,String.class},context,Uri.fromFile(f),id);}
    private boolean reject(File f,String id)throws Exception{try{Object prepared=prepare(f,id);call(prepared,"close",new Class[]{});return false;}catch(InvocationTargetException expected){return true;}}
    private void apply(Object prepared)throws Exception{call(prepared,"apply",new Class[]{Context.class},context);}
    private boolean finish(Object prepared,boolean okay)throws Exception{return (Boolean)call(prepared,"finish",new Class[]{Context.class,boolean.class},context,okay);}
    private void value(String id,boolean original){SharedPreferences.Editor edit=prefs(id+"_module").edit().clear();if(id.equals("music"))edit.putInt("volume_percent",original?40:60);else if(id.equals("messaging"))edit.putBoolean("notification_preview",original);else edit.putInt("views",original?3:7);check(edit.commit(),"fixture preferences committed");}
    private boolean original(String id){return id.equals("music")?prefs(id+"_module").getInt("volume_percent",0)==40:id.equals("messaging")?prefs(id+"_module").getBoolean("notification_preview",false):prefs(id+"_module").getInt("views",0)==3;}
    private void archives()throws Exception{
        for(String id:new String[]{"music","messaging","colorvision"}){
            remember(id+"_module");isolate(data(id));value(id,true);write(data(id),"attachments/value.txt","archived-"+id);File exported=exportApp(id);
            try(ZipFile zip=new ZipFile(exported)){JSONObject manifest=new JSONObject(new String(readEntry(zip,"internal.json"),StandardCharsets.UTF_8));check(id.equals(manifest.getString("module")),"archive has an explicit app identity");check(manifest.getJSONArray("apps").length()==1,"archive contains one app only");check(manifest.getJSONArray("apps").getJSONObject(0).getString("id").equals(id),"archive app identity matches data");}
            String other=id.equals("music")?"messaging":"music";check(reject(exported,other),"different app archive rejected");
            boolean wrongFull=false;try{Object prepared=call(type("InternalDataBackup"),"read",new Class[]{Context.class,Uri.class},context,Uri.fromFile(exported));call(prepared,"close",new Class[]{});}catch(InvocationTargetException expected){wrongFull=true;}check(wrongFull,"single app archive cannot replace all configuration");
            value(id,false);write(data(id),"attachments/value.txt","current-"+id);Object rollback=prepare(exported,id);apply(rollback);check(original(id),"import applies selected app preferences");check(read(new File(data(id),"attachments/value.txt")).equals("archived-"+id),"import applies selected app attachments");check(finish(rollback,false),"failed import rollback succeeds");check(!original(id),"rollback restores prior preferences");check(read(new File(data(id),"attachments/value.txt")).equals("current-"+id),"rollback restores prior attachments");
            Object prepared=prepare(exported,id);apply(prepared);check(finish(prepared,true),"successful app import finishes");check(original(id),"successful import retains restored preferences");check(read(new File(data(id),"attachments/value.txt")).equals("archived-"+id),"successful import retains restored attachments");
        }
        Map<String,Map<String,?>> empty=new LinkedHashMap<>();for(String g:new String[]{"toolbox","weather","status_places","status_routes","timetable","random_choice","todos"})empty.put(g,Collections.emptyMap());
        Object configuration=call(type("ConfigurationData"),"encode",new Class[]{Map.class,byte[].class},empty,null);File full=(File)call(type("InternalDataBackup"),"exportData",new Class[]{Context.class,byte[].class},context,configuration.toString().getBytes(StandardCharsets.UTF_8));outputs.add(full);check(reject(full,"music"),"full backup cannot be accidentally imported as one app");check(original("music"),"rejected import does not change preferences");
    }
    private byte[] readEntry(ZipFile zip,String name)throws Exception{try(InputStream in=zip.getInputStream(zip.getEntry(name));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
    private void ownership()throws Exception{
        Class<?> manager=type("ModuleDataManager"),registry=type("ModuleRegistry"),descriptor=type("ModuleRegistry$Module");Object global=call(registry,"find",new Class[]{String.class},"global");Class<?>[] allowed={descriptor,String.class,String.class};check((Boolean)call(registry,"allowed",allowed,global,"toolbox","ui_button_color"),"global data includes appearance");check(!(Boolean)call(registry,"allowed",allowed,global,"toolbox","astro_align_sky"),"global data excludes app settings");check(!(Boolean)call(registry,"allowed",allowed,global,"toolbox","weather_quota_test"),"global data excludes runtime safeguards");remember("toolbox");remember("random_choice");isolate(data("random"));isolate(cache("random"));
        prefs("toolbox").edit().putBoolean("random_animation",false).putBoolean("astro_align_sky",true).putInt("ui_button_color",123).putLong("weather_quota_test",12345).commit();prefs("random_choice").edit().putString("data","{\"kept\":true}").commit();
        File privateFile=write(data("random"),"saved.txt","private"),cacheFile=write(cache("random"),"temporary.txt","cache"),external=write(context.getCacheDir(),"qa-external-"+UUID.randomUUID()+".mp3","external audio");outputs.add(external);
        long[] sizes=(long[])call(manager,"measure",new Class[]{Context.class,String.class},context,"random");check(sizes[1]>=7&&sizes[2]>=5,"owned data and cache measured separately");
        call(manager,"clearCache",new Class[]{Context.class,String.class},context,"random");check(!cacheFile.exists(),"app cache removed");check(privateFile.isFile(),"cache cleanup retains private saved data");check(prefs("random_choice").contains("data"),"cache cleanup retains saved preferences");check(external.isFile(),"cache cleanup retains external audio");
        call(manager,"erase",new Class[]{Context.class,String.class},context,"random");check(!privateFile.exists(),"erase removes app private data");check(!prefs("random_choice").contains("data"),"erase removes app saved data");check(!prefs("toolbox").contains("random_animation"),"erase removes owned shared settings");check(prefs("toolbox").getBoolean("astro_align_sky",false),"erase retains another app settings");check(prefs("toolbox").getInt("ui_button_color",0)==123,"erase retains global appearance");check(prefs("toolbox").getLong("weather_quota_test",0)==12345,"erase retains API runtime safeguards");check(external.isFile(),"erase retains external audio");
        for(String id:new String[]{"music","messaging","colorvision"}){isolate(cache(id));File saved=write(data(id),"erase.txt","saved"),temp=write(cache(id),"erase.txt","temp");call(manager,"erase",new Class[]{Context.class,String.class},context,id);check(!saved.exists()&&!temp.exists(),"embedded app data and cache erased");check(prefs(id+"_module").getAll().isEmpty(),"embedded app preferences erased");}
        // An installed update can retain both its current executable and a rollback package.
        // Hold both so this fixture actually represents an uninstalled app with retained data.
        Map<File,File> held=new LinkedHashMap<>();
        try{
            call(type("ModuleRuntime"),"beginChange",new Class[]{Context.class,String.class},context,"colorvision");
            try{for(String name:new String[]{"colorvision.ddapp","colorvision.previous.ddapp"}){File program=new File(context.getFilesDir(),"apps/"+name);if(program.isFile()){File backup=new File(program.getParentFile(),"qa-colorvision-"+UUID.randomUUID()+".ddapp");Files.move(program.toPath(),backup.toPath());held.put(program,backup);}}}finally{call(type("ModuleRuntime"),"endChange",new Class[]{String.class},"colorvision");}
            prefs("colorvision_module").edit().putInt("views",2).commit();File retained=write(data("colorvision"),"retained.txt","retained");long[] absent=(long[])call(manager,"measure",new Class[]{Context.class,String.class},context,"colorvision");check(absent[0]==0&&absent[1]>=retained.length(),"uninstalled app retained data remains measurable");check(exportApp("colorvision").isFile(),"uninstalled app retained data remains exportable");
        }finally{
            call(type("ModuleRuntime"),"beginChange",new Class[]{Context.class,String.class},context,"colorvision");
            try{for(Map.Entry<File,File> entry:held.entrySet())if(entry.getValue().isFile())Files.move(entry.getValue().toPath(),entry.getKey().toPath());}finally{call(type("ModuleRuntime"),"endChange",new Class[]{String.class},"colorvision");}
        }
    }
    private Notification courseNotification(){for(android.service.notification.StatusBarNotification note:context.getSystemService(NotificationManager.class).getActiveNotifications())if("course".equals(note.getTag()))return note.getNotification();return null;}
    private void reminderDeletion()throws Exception{
        remember("toolbox");remember("todos");remember("todo_runtime");remember("timetable");
        prefs("toolbox").edit().putInt("seen_version",context.getPackageManager().getPackageInfo(context.getPackageName(),0).versionCode).commit();
        activity=startActivitySync(new Intent().setClassName(context,"org.daidai.toolbox.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();Field appField=activity.getClass().getDeclaredField("apps");appField.setAccessible(true);apps=appField.get(activity);
        for(String id:new String[]{"todo","schedule"}){boolean installed=(Boolean)call(apps,"installed",new Class[]{String.class},id);installedBefore.put(id,installed);if(!installed)try(InputStream in=new FileInputStream("/data/local/tmp/internal-apps/"+id+".ddapp")){call(apps,"install",new Class[]{InputStream.class,String.class,String.class},in,id,null);}check((Boolean)call(apps,"installed",new Class[]{String.class},id),"reminder app installed before deleting its data "+id);isolate(data(id));isolate(cache(id));}
        Object model=type("TodoModel").getConstructor().newInstance();prefs("todos").edit().putString("data",call(model,"json",new Class[]{}).toString()).commit();prefs("toolbox").edit().putBoolean("todo_notify",false).putBoolean("todo_summary",false).commit();File saved=write(data("todo"),"saved.txt","todo data");
        call(type("ModuleDataManager"),"erase",new Class[]{Context.class,String.class},context,"todo");check(!prefs("todos").contains("data")&&!saved.exists(),"installed todo data deletion completes");check(prefs("todo_runtime").getLong("not_before",0)>0,"todo scheduler resumes after data deletion");ClassLoader todoLoader=(ClassLoader)call(type("ModuleRuntime"),"loader",new Class[]{Context.class,String.class},context,"todo");Class<?> scheduler=Class.forName("org.daidai.toolbox.TodoSchedulerImpl",true,todoLoader);Field suspended=scheduler.getDeclaredField("suspended");suspended.setAccessible(true);check(!suspended.getBoolean(null),"todo scheduler is not left suspended");
        Object schedule=type("ScheduleModel").getConstructor().newInstance();java.time.LocalDateTime target=java.time.LocalDateTime.now().plusMinutes(5).withSecond(0).withNano(0);if(target.getHour()==23&&target.getMinute()>55)target=target.plusDays(1).withHour(0).withMinute(5);Class<?> slot=type("ScheduleModel$Slot"),course=type("ScheduleModel$Course");List slots=(List)type("ScheduleModel").getField("slots").get(schedule);slots.clear();slots.add(slot.getConstructor(String.class,String.class).newInstance(target.toLocalTime().toString(),target.plusMinutes(1).toLocalTime().toString()));type("ScheduleModel").getField("semester").set(schedule,target.toLocalDate().with(java.time.DayOfWeek.MONDAY));Object row=course.getConstructor().newInstance();course.getField("name").set(row,"Delete active course reminder");course.getField("day").setInt(row,target.getDayOfWeek().getValue());((List)type("ScheduleModel").getField("courses").get(schedule)).add(row);prefs("timetable").edit().putString("data",call(schedule,"json",new Class[]{}).toString()).commit();prefs("toolbox").edit().putBoolean("course_notify",true).putInt("course_notify_lead",30).putInt("course_notify_remove",10).commit();
        call(type("ScheduleNotifier"),"refresh",new Class[]{Context.class,boolean.class},context,true);await(()->{Notification note=courseNotification();return note!=null&&"Delete active course reminder".contentEquals(note.extras.getCharSequence(Notification.EXTRA_TITLE,""));},"actual course reminder is active before data deletion");File courseData=write(data("schedule"),"saved.txt","course data");prefs("todo_runtime").edit().putString("qa_course_delete_keep","keep").commit();
        call(type("ModuleDataManager"),"erase",new Class[]{Context.class,String.class},context,"schedule");check(!prefs("timetable").contains("data")&&!courseData.exists(),"installed course data deletion completes");await(()->courseNotification()==null,"deleting course data removes its active notification");check((Boolean)call(apps,"installed",new Class[]{String.class},"schedule"),"deleting course data retains executable");check(prefs("todo_runtime").getString("qa_course_delete_keep","").equals("keep"),"course deletion does not reset todo scheduler runtime");
    }
    private void restore()throws Exception{for(Map.Entry<String,Map<String,?>> e:preferences.entrySet())call(type("ConfigurationTransfer"),"write",new Class[]{SharedPreferences.class,Map.class},prefs(e.getKey()),e.getValue());for(Map.Entry<File,File> e:directories.entrySet()){remove(e.getKey());if(e.getValue().exists())Files.move(e.getValue().toPath(),e.getKey().toPath());}for(File f:outputs)remove(f);for(Map.Entry<String,Boolean> app:installedBefore.entrySet())if(!app.getValue()){ui(()->{try{call(apps,"uninstall",new Class[]{String.class},app.getKey());}catch(Exception failure){throw new RuntimeException(failure);}});Field busy=apps.getClass().getField("busy");await(()->{try{return !busy.getBoolean(null);}catch(Exception failure){return false;}},"fixture app uninstall completes");}if(context!=null){call(type("TodoScheduler"),"refresh",new Class[]{Context.class,boolean.class},context,false);call(type("ScheduleNotifier"),"refresh",new Class[]{Context.class,boolean.class},context,false);}}
    private void remove(File file)throws Exception{if(!file.exists())return;if(file.isDirectory()&&!Files.isSymbolicLink(file.toPath())){File[] children=file.listFiles();if(children!=null)for(File child:children)remove(child);}if(!file.delete())throw new IOException("Cannot clean test fixture");}
    public void onStart(){Bundle result=new Bundle();try{context=getTargetContext();loader=context.getClassLoader();archives();ownership();reminderDeletion();result.putString("result","PASS: "+checks+" app data isolation checks");}catch(Throwable failure){StringWriter log=new StringWriter();failure.printStackTrace(new PrintWriter(log));result.putString("result","FAIL: "+log);}finally{try{restore();}catch(Throwable failure){result.putString("result",result.getString("result")+"\nFixture restore failed: "+failure);}if(activity!=null)ui(()->activity.finish());finish(Activity.RESULT_OK,result);}}
}
